(2075, 'negotiate', '/nɪˈɡoʊʃieɪt/', 'verb', '{"zh-TW":["談判；協商","磋商","協商"],"en":["to try to reach an agreement through discussion","to discuss to reach an agreement","to deal with something","to reach an agreement through discussion"]}', '{"prefix":{"text":"neg-","meaning":"not (不)"},"root":{"text":"oti","meaning":"leisure (閒暇)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"非閒暇之事（嚴肅處理），即「談判」。"}', 'negotiate a deal / negotiate terms / negotiate a contract; negotiate with sb. / negotiate a deal; negotiate terms / negotiate a salary', '[{"en":"The two sides are negotiating a peace agreement.","zh-TW":"雙方正在協商和平協議。"},{"en":"She negotiated a higher salary.","zh-TW":"她談判爭取到了更高的薪水。"},{"en":"The union is negotiating with management for better wages.","zh-TW":"工會正在與管理層協商更高的薪資。"},{"en":"We negotiated a 10% discount.","zh-TW":"我們談成了九折優惠。"},{"en":"She successfully negotiated better terms.","zh-TW":"她成功談成了更好的條件。"},{"en":"New hires can negotiate their salary.","zh-TW":"新員工可以協商薪資。"}]', '{"noun":"negotiation","noun2":"negotiator","adjective":"negotiable"}', NULL, 3, 2075, 39),
(2076, 'negotiation', '/nɪˌɡoʊʃiˈeɪʃən/', 'noun', '{"zh-TW":["談判；協商"],"en":["a discussion aimed at reaching a mutually acceptable agreement"]}', NULL, 'contract negotiation / salary negotiation / enter negotiations / negotiation tactics', '[{"en":"The negotiation lasted three days before a deal was reached.","zh-TW":"談判持續了三天才達成協議。"},{"en":"Preparation is the key to successful negotiation.","zh-TW":"準備是成功談判的關鍵。"}]', '{"verb":"negotiate","noun":"negotiator","adjective":"negotiable"}', NULL, 4, 2076, 598),
