(2093, 'nominal', '/ˈnɒmɪnəl/', 'adjective', '{"zh-TW":["名義上的","象徵性的"],"en":["in name only","very small"]}', '{"root":{"text":"nomin","meaning":"name (名字)"},"suffix":{"text":"-al","meaning":"...的"}}', 'nominal fee / nominal value', '[{"en":"They charge a nominal fee for the service.","zh-TW":"他們收取象徵性費用。"},{"en":"He is the nominal leader of the organization.","zh-TW":"他是名義上的領導人。"}]', '{"adverb":"nominally","verb":"nominate","noun":"nomination"}', NULL, 3, 2093, 896),
(2094, 'nominate', '/ˈnɒmɪneɪt/', 'verb', '{"zh-TW":["提名；任命"],"en":["to suggest someone for a position"]}', '{"root":{"text":"nomin","meaning":"name (名字)"},"suffix":{"text":"-ate","meaning":"使..."}}', 'nominate sb. for / be nominated', '[{"en":"She was nominated for Employee of the Year.","zh-TW":"她被提名為年度最佳員工。"},{"en":"The board nominated him as chairman.","zh-TW":"董事會提名他為主席。"}]', '{"noun":"nomination, nominee","adjective":"nominal"}', NULL, 3, 2094, NULL),
(2095, 'non-alcoholic', '/ˌnɒn ˌælkəˈhɒlɪk/', 'adjective', '{"zh-TW":["不含酒精的；非酒精的"],"en":["containing no alcohol"]}', NULL, 'non-alcoholic beverage / non-alcoholic option', '[{"en":"The menu includes a wide range of non-alcoholic beverages.","zh-TW":"菜單包含各種不含酒精的飲料。"},{"en":"She ordered a non-alcoholic cocktail.","zh-TW":"她點了一杯非酒精雞尾酒。"}]', NULL, NULL, 5, 2095, NULL),
(2096, 'non-compete', '/nɒn kəmˈpiːt/', 'noun', '{"zh-TW":["競業禁止協議"],"en":["an agreement not to work for competitors after leaving"]}', NULL, 'non-compete clause / sign a non-compete', '[{"en":"The employee signed a non-compete agreement.","zh-TW":"員工簽署了競業禁止協議。"},{"en":"The non-compete clause lasts for two years after termination.","zh-TW":"競業禁止條款在終止後持續兩年。"}]', NULL, NULL, 4, 2096, NULL),
(2097, 'non-refundable', '/ˌnɒn rɪˈfʌndəbəl/', 'adjective', '{"zh-TW":["不可退款的"],"en":["not eligible for a refund"]}', NULL, 'non-refundable deposit / non-refundable booking', '[{"en":"The advance booking rate is non-refundable.","zh-TW":"提前預訂價格不可退款。"},{"en":"Read the terms carefully as some rates are non-refundable.","zh-TW":"請仔細閱讀條款，因為有些價格不可退款。"}]', NULL, NULL, 5, 2097, NULL),
(2098, 'nondisclosure', '/ˌnɒndɪsˈkləʊʒər/', 'noun', '{"zh-TW":["保密；不披露"],"en":["the practice of keeping information confidential"]}', NULL, 'nondisclosure requirement / nondisclosure policy', '[{"en":"The nondisclosure requirement applies to all contractors.","zh-TW":"保密要求適用於所有承包商。"},{"en":"Violation of the nondisclosure policy may result in termination.","zh-TW":"違反保密政策可能導致解僱。"}]', NULL, NULL, 5, 2098, NULL),
(2099, 'nonstop', '/ˈnɒnstɒp/', 'adjective', '{"zh-TW":["不停站的；直飛的"],"en":["continuing without any stops"]}', NULL, 'nonstop flight / nonstop service', '[{"en":"There is a nonstop flight from Taipei to New York.","zh-TW":"台北到紐約有直飛航班。"},{"en":"We prefer nonstop flights for long-distance travel.","zh-TW":"長途旅行我們偏好直飛航班。"}]', '{"adverb":"nonstop"}', NULL, 3, 2099, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2100, 'norm', '/nɔːrm/', 'noun', '{"zh-TW":["規範；標準","常態"],"en":["a standard","the usual state"]}', '{"root":{"text":"norm","meaning":"rule (規則)"}}', 'social norm / above the norm', '[{"en":"Working from home has become the norm.","zh-TW":"在家工作已成為常態。"},{"en":"Safety standards exceed industry norms.","zh-TW":"安全標準超過行業規範。"}]', '{"adjective":"normal, normative","verb":"normalize","adverb":"normally"}', NULL, 1, 2100, NULL),
(2101, 'normal', '/ˈnɔːrməl/', 'adjective', '{"zh-TW":["正常的；一般的","正常的"],"en":["usual; typical; expected","usual; typical"]}', '{"root":{"text":"norm","meaning":"rule (規則)"},"suffix":{"text":"-al","meaning":"...的"}}', 'return to normal / normal procedure; return to normal / normal hours / new normal', '[{"en":"Business operations have returned to normal.","zh-TW":"業務運營已恢復正常。"},{"en":"This is normal procedure for new hires.","zh-TW":"這是新員工的正常流程。"},{"en":"Business hours have returned to normal.","zh-TW":"營業時間已恢復正常。"},{"en":"Remote work is the new normal.","zh-TW":"遠程工作是新常態。"}]', '{"noun":"normality, norm","verb":"normalize","adverb":"normally"}', NULL, 2, 2101, NULL),
(2102, 'normalization', '/ˌnɔːrməlaɪˈzeɪʃən/', 'noun', '{"zh-TW":["正常化；規範化"],"en":["the process of adjusting data or financial figures to reflect normal operating conditions"]}', NULL, 'apply normalization / earnings normalization', '[{"en":"Analysts apply normalization adjustments to remove one-time items from earnings.","zh-TW":"分析師應用正常化調整以從盈利中剔除一次性項目。"},{"en":"Interest rate normalization is the process of returning to typical rate levels.","zh-TW":"利率正常化是恢復到典型利率水平的過程。"}]', '{"verb":"normalize","adjective":"normalized"}', NULL, 5, 2102, NULL),
(2103, 'north', '/nɔːrθ/', 'noun', '{"zh-TW":["北方"],"en":["the direction opposite to south"]}', NULL, 'north of / up north', '[{"en":"The factory is north of the city.","zh-TW":"工廠在城市北邊。"},{"en":"We are expanding up north.","zh-TW":"我們正在向北方擴展。"}]', '{"noun":"north","adjective":"northern","adverb":"northward"}', NULL, 2, 2103, NULL),
(2104, 'notable', '/ˈnoʊtəbl/', 'adjective', '{"zh-TW":["值得注意的；顯著的"],"en":["worthy of attention; remarkable"]}', '{"root":{"text":"not","meaning":"mark (標記)"},"suffix":{"text":"-able","meaning":"能...的"}}', 'notable achievement / most notably', '[{"en":"There has been a notable improvement in sales.","zh-TW":"銷售額有顯著改善。"},{"en":"The city is notable for its architecture.","zh-TW":"這城市以建築聞名。"}]', '{"adverb":"notably","noun":"notability"}', NULL, 3, 2104, NULL),
(2105, 'notarize', '/ˈnəʊtəraɪz/', 'verb', '{"zh-TW":["公證；公證認證"],"en":["to have a document officially certified by a notary"]}', NULL, 'notarize a document / notarize a signature', '[{"en":"The contract must be notarized before it is valid.","zh-TW":"合約在公證前無效。"},{"en":"She took the deed to a notary to have it notarized.","zh-TW":"她將契約帶到公證人處進行公證。"}]', '{"noun":"notarization","noun2":"notary","adjective":"notarized"}', NULL, 3, 2105, NULL),
(2106, 'notation', '/noʊˈteɪʃən/', 'noun', '{"zh-TW":["符號；標記"],"en":["a system of symbols used to represent information"]}', NULL, 'accounting notation / mathematical notation / make a notation', '[{"en":"The accountant used standard notation for all financial entries.","zh-TW":"會計師對所有財務分錄使用了標準符號。"},{"en":"Please make a notation on the file to indicate the new terms.","zh-TW":"請在檔案上作標記以指明新條款。"}]', '{"verb":"notate","adjective":"notated"}', NULL, 3, 2106, NULL),
(2107, 'note', '/noʊt/', 'noun', '{"zh-TW":["筆記；注意"],"en":["a short written message","to pay attention to"]}', NULL, 'take note / please note', '[{"en":"Please note the new office hours.","zh-TW":"請注意新的辦公時間。"},{"en":"I took notes during the meeting.","zh-TW":"我在會議中做了筆記。"}]', '{"noun":"note","verb":"note","adjective":"noteworthy","noun2":"notebook"}', NULL, 1, 2107, NULL),
(2108, 'notice', '/ˈnoʊtɪs/', 'noun', '{"zh-TW":["通知；公告","注意"],"en":["a written announcement","attention"]}', '{"root":{"text":"not","meaning":"know (知道)"},"suffix":{"text":"-ice","meaning":"名詞後綴"}}', 'give notice / at short notice / until further notice', '[{"en":"Please give two weeks'' notice before resigning.","zh-TW":"辭職前請提前兩週通知。"},{"en":"The change takes effect until further notice.","zh-TW":"變更持續有效直到另行通知。"}]', '{"adjective":"noticeable","adverb":"noticeably","verb":"notice"}', NULL, 2, 2108, 398),
(2109, 'notification', 'ˌnoʊtɪfɪˈkeɪʃən', 'noun', '{"zh-TW":["通知；公告","提醒"],"en":["an official message or alert","an announcement"]}', NULL, 'send a notification/receive notification', '[{"en":"You will receive a notification by email.","zh-TW":"您將通過電子郵件收到通知。"}]', '{"verb":"notify","adjective":"notified"}', NULL, 4, 2109, 599),
(2110, 'notify', '/ˈnoʊtɪfaɪ/', 'verb', '{"zh-TW":["通知；告知"],"en":["to formally inform someone"]}', '{"root":{"text":"not","meaning":"know (知道)"},"suffix":{"text":"-ify","meaning":"使...化"}}', 'notify sb. of sth. / notify in writing', '[{"en":"We will notify you of any schedule changes.","zh-TW":"我們會通知您時間表的變更。"},{"en":"All employees must be notified in advance.","zh-TW":"所有員工必須提前被通知。"}]', '{"noun":"notification","adjective":"notifiable"}', NULL, 2, 2110, 40),
(2111, 'notion', '/ˈnoʊʃən/', 'noun', '{"zh-TW":["概念；想法"],"en":["a concept or belief"]}', '{"root":{"text":"not","meaning":"know (知道)"},"suffix":{"text":"-ion","meaning":"名詞後綴"}}', 'the notion that / preconceived notion', '[{"en":"She rejected the notion that women cannot lead.","zh-TW":"她駁斥了女性不能領導的觀念。"},{"en":"He has no notion of the difficulty.","zh-TW":"他不知道有多困難。"}]', '{"adjective":"notional"}', NULL, 2, 2111, NULL),
(2112, 'notwithstanding', '/ˌnɒtwɪθˈstændɪŋ/', 'preposition', '{"zh-TW":["儘管；雖然"],"en":["in spite of; despite"]}', NULL, 'notwithstanding the fact that', '[{"en":"Notwithstanding the challenges, it was completed on time.","zh-TW":"儘管有挑戰，仍按時完成。"},{"en":"The contract is valid notwithstanding minor errors.","zh-TW":"儘管有小錯，合約仍有效。"}]', NULL, NULL, 5, 2112, NULL),
(2113, 'novel', '/ˈnɒvəl/', 'adjective', '{"zh-TW":["新穎的；新奇的"],"en":["new and original"]}', '{"root":{"text":"nov","meaning":"new (新的)"},"suffix":{"text":"-el","meaning":"後綴"}}', 'novel approach / novel idea', '[{"en":"The team proposed a novel approach.","zh-TW":"團隊提出了新穎的方法。"},{"en":"This is a novel concept in marketing.","zh-TW":"這是行銷的新穎概念。"}]', '{"noun":"novelty, novelist"}', NULL, 2, 2113, NULL),
(2114, 'number', '/ˈnʌmbər/', 'noun', '{"zh-TW":["數字；號碼"],"en":["a mathematical value","a quantity"]}', NULL, 'a number of / phone number', '[{"en":"A number of clients have complained.","zh-TW":"許多客戶投訴了。"},{"en":"What is your phone number?","zh-TW":"你的電話號碼是什麼？"}]', '{"noun":"number","verb":"number","adjective":"numerous","adjective2":"numerical"}', NULL, 2, 2114, NULL),
(2115, 'numerous', '/ˈnjuːmərəs/', 'adjective', '{"zh-TW":["許多的；眾多的"],"en":["great in number; many"]}', '{"root":{"text":"numer","meaning":"number (數字)"},"suffix":{"text":"-ous","meaning":"充滿...的"}}', 'numerous occasions / numerous studies', '[{"en":"The company received numerous complaints.","zh-TW":"公司收到大量投訴。"},{"en":"She published numerous articles.","zh-TW":"她發表了許多文章。"}]', '{"adverb":"numerously","noun":"number"}', NULL, 3, 2115, NULL),
(2116, 'nurse', '/nɜːrs/', 'noun', '{"zh-TW":["護士"],"en":["a person trained to care for sick people"]}', NULL, 'registered nurse / nurse practitioner', '[{"en":"The company clinic has two registered nurses.","zh-TW":"公司診所有兩位註冊護士。"},{"en":"She trained as a nurse before going into management.","zh-TW":"她在從事管理工作前受過護士訓練。"}]', '{"noun":"nurse","noun2":"nursing","verb":"nurse"}', NULL, 2, 2116, NULL),
(2117, 'nurture', '/ˈnɜːrtʃər/', 'verb', '{"zh-TW":["培養；養育"],"en":["to care for and encourage growth"]}', '{"root":{"text":"nutr","meaning":"nourish (滋養)"},"suffix":{"text":"-ure","meaning":"行為"}}', 'nurture talent / nurture relationships', '[{"en":"The manager nurtures young talent.","zh-TW":"經理培養年輕人才。"},{"en":"Nurture good relationships with clients.","zh-TW":"培養與客戶的良好關係。"}]', '{"noun":"nurture, nurturer","adjective":"nurturing"}', NULL, 3, 2117, NULL),
(2118, 'oath', '/oʊθ/', 'noun', '{"zh-TW":["宣誓；誓言"],"en":["a formal promise to tell the truth"]}', NULL, 'take an oath / under oath', '[{"en":"She took an oath of office.","zh-TW":"她進行了就職宣誓。"},{"en":"He lied under oath.","zh-TW":"他在宣誓後說謊。"}]', NULL, NULL, 1, 2118, NULL),
(2119, 'obey', '/oʊˈbeɪ/', 'verb', '{"zh-TW":["服從；遵守"],"en":["to do what you are told"]}', '{"prefix":{"text":"ob-","meaning":"toward"},"root":{"text":"ey","meaning":"hear"}}', 'obey the rules / obey orders', '[{"en":"All employees must obey company regulations.","zh-TW":"所有員工必須遵守公司規定。"},{"en":"Citizens are expected to obey the law.","zh-TW":"公民應遵守法律。"}]', '{"noun":"obedience","adjective":"obedient","adverb":"obediently"}', NULL, 1, 2119, NULL),
(2120, 'object', '/əbˈdʒɛkt/', 'verb', '{"zh-TW":["反對"],"en":["to express disagreement"]}', '{"prefix":{"text":"ob-","meaning":"against"},"root":{"text":"ject","meaning":"throw (投擲)"}}', 'object to sth.', '[{"en":"Several members objected to the proposal.","zh-TW":"幾位成員反對該提案。"},{"en":"No one objected to the new policy.","zh-TW":"沒人反對新政策。"}]', '{"noun":"objection, object","adjective":"objectionable"}', NULL, 2, 2120, NULL),
(2121, 'objective', '/əbˈdʒɛktɪv/', 'noun', '{"zh-TW":["目標；目的"],"en":["a goal or aim"]}', '{"prefix":{"text":"ob-","meaning":"toward"},"root":{"text":"ject","meaning":"throw"},"suffix":{"text":"-ive","meaning":"...的"}}', 'meet an objective / objective assessment', '[{"en":"Our main objective is to increase market share.","zh-TW":"我們的主要目標是增加市場份額。"},{"en":"Try to remain objective when evaluating.","zh-TW":"評估時請保持客觀。"}]', '{"noun":"objectivity","adverb":"objectively"}', NULL, 3, 2121, 163),
(2122, 'objective-based', 'əbˈdʒɛktɪv beɪst', 'adjective', '{"zh-TW":["基於目標的；目標導向的","以目標為依據的"],"en":["guided by specific objectives","goal-focused"]}', NULL, 'objective-based management/objective-based review', '[{"en":"Our evaluation is objective-based.","zh-TW":"我們的評估是基於目標的。"}]', NULL, NULL, 5, 2122, NULL),
(2123, 'obligation', '/ˌɒblɪˈɡeɪʃən/', 'noun', '{"zh-TW":["義務；責任"],"en":["something you must do"]}', '{"root":{"text":"oblig","meaning":"bind (綁定)"},"suffix":{"text":"-ation","meaning":"狀態"}}', 'legal obligation / under no obligation', '[{"en":"You are under no obligation to accept.","zh-TW":"你沒有義務接受。"},{"en":"The company has an obligation to shareholders.","zh-TW":"公司對股東有責任。"}]', '{"verb":"oblige","adjective":"obligatory, obliging"}', NULL, 4, 2123, 399),
(2124, 'observe', '/əbˈzɜːrv/', 'verb', '{"zh-TW":["觀察","遵守"],"en":["to watch carefully","to obey a rule"]}', '{"prefix":{"text":"ob-","meaning":"over"},"root":{"text":"serv","meaning":"watch (看)"}}', 'observe changes / observe rules', '[{"en":"Scientists observed a significant change.","zh-TW":"科學家觀察到顯著變化。"},{"en":"All visitors must observe safety regulations.","zh-TW":"訪客必須遵守安全規定。"}]', '{"noun":"observation, observer","adjective":"observant, observable"}', NULL, 3, 2124, NULL),
(2125, 'obsolete', '/ˈɒbsəliːt/', 'adjective', '{"zh-TW":["過時的；淘汰的"],"en":["no longer in use"]}', '{"prefix":{"text":"ob-","meaning":"away"},"root":{"text":"sol","meaning":"use (使用)"}}', 'become obsolete / obsolete technology', '[{"en":"This software has become obsolete.","zh-TW":"這個軟體已經過時。"},{"en":"New technology rendered the old system obsolete.","zh-TW":"新技術使舊系統過時。"}]', '{"noun":"obsolescence"}', NULL, 3, 2125, NULL),
(2126, 'obstacle', '/ˈɒbstəkl/', 'noun', '{"zh-TW":["障礙"],"en":["something that blocks progress"]}', '{"prefix":{"text":"ob-","meaning":"against"},"root":{"text":"sta","meaning":"stand (站)"}}', 'overcome an obstacle / major obstacle', '[{"en":"Lack of funding is a major obstacle.","zh-TW":"缺乏資金是主要障礙。"},{"en":"She overcame many obstacles.","zh-TW":"她克服了許多障礙。"}]', NULL, NULL, 3, 2126, NULL),
(2127, 'obtain', '/əbˈteɪn/', 'verb', '{"zh-TW":["獲得；取得"],"en":["to get or acquire something","to get something by effort"]}', '{"prefix":{"text":"ob-","meaning":"toward (朝向)"},"root":{"text":"tain","meaning":"hold (持有)"},"logic":"朝向持有而得到，即「獲得」。"}', 'obtain permission / obtain information / obtain a degree', '[{"en":"You must obtain permission before entering.","zh-TW":"進入前必須獲得許可。"},{"en":"She obtained her PhD from Harvard.","zh-TW":"她從哈佛取得了博士學位。"},{"en":"You must obtain approval before proceeding.","zh-TW":"你必須獲得批准才能繼續。"},{"en":"Details can be obtained from our website.","zh-TW":"詳情可從網站獲取。"}]', '{"adjective":"obtainable"}', NULL, 2, 2127, 41),
(2128, 'obvious', '/ˈɒbviəs/', 'adjective', '{"zh-TW":["明顯的"],"en":["easy to see or understand"]}', '{"prefix":{"text":"ob-","meaning":"in the way"},"root":{"text":"vi","meaning":"way (路)"},"suffix":{"text":"-ous","meaning":"...的"}}', 'obvious reason / it is obvious that', '[{"en":"It is obvious that we need to cut costs.","zh-TW":"很明顯我們需要削減成本。"},{"en":"The answer was obvious to everyone.","zh-TW":"答案對所有人都顯而易見。"}]', '{"adverb":"obviously","noun":"obviousness"}', NULL, 3, 2128, NULL),
(2129, 'occasion', '/əˈkeɪʒən/', 'noun', '{"zh-TW":["場合；時機"],"en":["a particular time or event"]}', '{"prefix":{"text":"oc-","meaning":"toward"},"root":{"text":"cas","meaning":"fall (落)"}}', 'on this occasion / special occasion / on occasion', '[{"en":"On this occasion, we will make an exception.","zh-TW":"這次我們將破例。"},{"en":"The dinner was a formal occasion.","zh-TW":"晚餐是正式場合。"}]', '{"adjective":"occasional","adverb":"occasionally"}', NULL, 3, 2129, NULL),
(2130, 'occupancy', '/ˈɒkjʊpənsi/', 'noun', '{"zh-TW":["入住率；佔用"],"en":["the use of a room or building"]}', NULL, 'full occupancy / occupancy rate', '[{"en":"The hotel reached full occupancy during the festival.","zh-TW":"節日期間飯店入住率達到最高。"},{"en":"The occupancy rate dropped during the off-season.","zh-TW":"淡季期間入住率下降。"}]', '{"verb":"occupy","adjective":"occupied"}', NULL, 3, 2130, 164),
(2131, 'occupy', '/ˈɒkjupaɪ/', 'verb', '{"zh-TW":["占據；使忙碌","佔據","使忙碌"],"en":["to fill or take up a space or time","to fill or take up space","to keep busy"]}', '{"prefix":{"text":"oc-","meaning":"over (在上)"},"root":{"text":"cupy","meaning":"seize (佔有)"},"logic":"佔有其上，即「占據」。"}', 'occupy a position / occupy space / occupied with; occupy a position / be occupied with', '[{"en":"The meeting occupied the entire morning.","zh-TW":"會議佔了整個早上。"},{"en":"She is occupied with work right now.","zh-TW":"她現在忙於工作。"},{"en":"The department occupies the entire third floor.","zh-TW":"部門佔據了整個三樓。"},{"en":"She has been occupied with the merger.","zh-TW":"她一直忙於合併事宜。"}]', '{"noun":"occupation","adjective":"occupied"}', NULL, 2, 2131, NULL),
(2132, 'occur', '/əˈkɜːr/', 'verb', '{"zh-TW":["發生","想到"],"en":["to happen","to come into mind"]}', '{"prefix":{"text":"oc-","meaning":"toward"},"root":{"text":"cur","meaning":"run (跑)"}}', 'occur frequently / it occurs to sb.', '[{"en":"The error occurred during the update.","zh-TW":"錯誤發生在更新期間。"},{"en":"It never occurred to me to check.","zh-TW":"我從未想到要檢查。"}]', '{"noun":"occurrence"}', NULL, 2, 2132, NULL),
(2133, 'ocean', '/ˈoʊʃən/', 'noun', '{"zh-TW":["海洋"],"en":["a very large area of sea"]}', NULL, 'ocean freight / across the ocean', '[{"en":"Ocean freight is cheaper than air freight.","zh-TW":"海運比空運便宜。"},{"en":"Our products ship across the ocean.","zh-TW":"我們的產品跨洋運送。"}]', '{"noun":"ocean","adjective":"oceanic"}', NULL, 2, 2133, NULL),
(2134, 'odd', '/ɒd/', 'adjective, noun (plural)', '{"zh-TW":["【主要意義-形容詞】奇怪的；不尋常的","【次要意義-形容詞】奇數的（不能被2整除）","【次要意義-形容詞】剩餘的；臨時的；偶爾的","【次要意義-複數名詞（odds）】機率；可能性；不平等"],"en":["[primary - adjective] strange or unusual","[secondary - adjective] not divisible by two","[secondary - adjective] extra; occasional; not regular","[secondary - plural noun] probability; the likelihood of something happening"]}', NULL, 'odd jobs / odd numbers / at odds with / odds are / against all odds', '[{"en":"The odds of winning the contract are in our favor after the presentation.","zh-TW":"提案後，贏得合約的勝算對我們有利。"},{"en":"He does odd jobs around the office such as filing and photocopying.","zh-TW":"他在辦公室做一些零散工作，如歸檔和影印。"},{"en":"Management was at odds with the union over the new pay structure.","zh-TW":"管理層與工會在新薪酬結構問題上存在分歧。"}]', '{"adverb":"oddly","noun":"oddity"}', 'odds（機率/勝算）、at odds with（與……有分歧）、odd jobs（零散工作）均為 TOEIC 商業文章常見詞彙，考生只知道「奇怪」的意思會造成閱讀障礙。', 1, 2134, NULL),
(2135, 'off-balance-sheet', '/ˌɒf ˈbæləns ʃiːt/', 'adjective', '{"zh-TW":["表外的；資產負債表外的"],"en":["referring to assets or liabilities not recorded on the balance sheet"]}', NULL, 'off-balance-sheet financing / off-balance-sheet liability', '[{"en":"Operating leases can keep debt off-balance-sheet under older accounting rules.","zh-TW":"在較舊的會計準則下，經營租賃可以將債務保持在表外。"},{"en":"Off-balance-sheet items can obscure the true financial position of a company.","zh-TW":"表外項目可能掩蓋公司的真實財務狀況。"}]', NULL, NULL, 5, 2135, NULL),
(2136, 'off-plan', '/ˌɒf ˈplæn/', 'adjective', '{"zh-TW":["按圖紙購買的；期房的"],"en":["bought or sold based on plans before a property is built"]}', NULL, 'buy off-plan / off-plan purchase / off-plan development', '[{"en":"She purchased the apartment off-plan at a discounted price.","zh-TW":"她以折扣價購買了期房公寓。"},{"en":"Off-plan purchases carry more risk but offer better initial pricing.","zh-TW":"期房購買風險更高，但提供更好的初始定價。"}]', NULL, NULL, 3, 2136, NULL),
(2137, 'offboarding', '/ˈɒfˌbɔːrdɪŋ/', 'noun', '{"zh-TW":["離職流程"],"en":["the process of managing an employee''s departure from a company"]}', NULL, 'offboarding checklist / offboarding process / employee offboarding', '[{"en":"The HR team conducted an offboarding interview with departing staff.","zh-TW":"人力資源團隊對離職員工進行了離職面談。"},{"en":"Proper offboarding ensures knowledge is transferred before departure.","zh-TW":"適當的離職流程確保在離職前完成知識轉移。"}]', '{"verb":"offboard"}', NULL, 4, 2137, NULL),
(2138, 'offer', '/ˈɒfər/', 'noun', '{"zh-TW":["提議；出價；優惠","提供；提議"],"en":["something proposed or available","a reduced price for a limited time","to present for acceptance"]}', '{"prefix":{"text":"of-","meaning":"toward (朝向)"},"root":{"text":"fer","meaning":"carry (帶來)"},"logic":"帶向某人，即「提供」。"}', 'special offer / make an offer; offer a discount / job offer / make an offer', '[{"en":"The store has a special offer on electronics.","zh-TW":"這家店有電子產品特惠。"},{"en":"He made an offer on the house.","zh-TW":"他對那棟房子出了價。"},{"en":"They offered me a position in marketing.","zh-TW":"他們給我一個行銷職位。"},{"en":"We offer a 15% discount on bulk orders.","zh-TW":"大量訂購可享15%折扣。"}]', '{"verb":"offer","noun":"offer, offering"}', NULL, 2, 2138, 165),
(2139, 'office', '/ˈɒfɪs/', 'noun', '{"zh-TW":["辦公室"],"en":["a place where business work is done"]}', NULL, 'head office / office supplies', '[{"en":"Our head office is in Taipei.","zh-TW":"我們的總部在台北。"},{"en":"Order office supplies from the catalog.","zh-TW":"從目錄訂購辦公用品。"}]', '{"noun":"office","noun2":"officer","adjective":"official","adverb":"officially"}', NULL, 2, 2139, NULL),
(2140, 'official', 'əˈfɪʃəl', 'adjective', '{"zh-TW":["官方的；正式的","公認的"],"en":["authorized by authority","formal"]}', NULL, 'official document/official approval', '[{"en":"Please use the official company letterhead.","zh-TW":"請使用公司官方信紙。"}]', '{"noun":"official","adverb":"officially"}', NULL, 3, 2140, 166),
(2141, 'offset', '/ˈɒfsɛt/', 'verb', '{"zh-TW":["抵消；彌補"],"en":["to balance or compensate"]}', '{"prefix":{"text":"off-","meaning":"away"},"root":{"text":"set","meaning":"place (放)"}}', 'offset costs / offset losses', '[{"en":"The gains offset the earlier losses.","zh-TW":"收益抵消了早期損失。"},{"en":"Higher sales offset increased costs.","zh-TW":"更高銷售額抵消了成本增加。"}]', '{"noun":"offset"}', NULL, 2, 2141, 701),
(2142, 'offshore', '/ˈɒfʃɔːr/', 'adjective', '{"zh-TW":["境外的；離岸的"],"en":["located or occurring outside one''s home country"]}', NULL, 'offshore account / offshore investment / offshore manufacturing', '[{"en":"The company opened an offshore account to manage foreign currency.","zh-TW":"公司開設了一個境外帳戶來管理外幣。"},{"en":"Offshore manufacturing reduced production costs significantly.","zh-TW":"境外製造顯著降低了生產成本。"}]', '{"verb":"offshore","adverb":"offshore"}', NULL, 3, 2142, NULL),
(2143, 'offshoring', '/ˈɒfʃɔːrɪŋ/', 'noun', '{"zh-TW":["離岸外包；境外遷移"],"en":["moving business operations to a foreign country"]}', NULL, 'offshoring of jobs / offshoring strategy', '[{"en":"Offshoring manufacturing helped reduce production costs.","zh-TW":"將製造業務遷移海外有助於降低生產成本。"},{"en":"Critics argue that offshoring harms domestic workers.","zh-TW":"批評者認為離岸外包損害了本國工人的利益。"}]', '{"verb":"offshore","adjective":"offshore"}', NULL, 4, 2143, NULL),
(2144, 'offsite', '/ˈɒfsaɪt/', 'adjective', '{"zh-TW":["場外的；外地的"],"en":["taking place or located away from the main workplace or premises"]}', NULL, 'offsite meeting / offsite training / offsite team building', '[{"en":"The management team held an offsite retreat for strategic planning.","zh-TW":"管理團隊舉行了外地靜修活動進行策略規劃。"},{"en":"Offsite data storage provides protection against local disasters.","zh-TW":"場外資料存儲提供了對本地災難的保護。"}]', '{"adverb":"offsite"}', NULL, 3, 2144, NULL),
(2145, 'OKR', '/ˌoʊ keɪ ˈɑːr/', 'noun', '{"zh-TW":["目標與關鍵結果"],"en":["objectives and key results; a goal-setting framework"]}', NULL, 'set OKRs / OKR framework / quarterly OKRs', '[{"en":"The company adopted OKRs to align team and company goals.","zh-TW":"公司採用OKR框架使團隊和公司目標保持一致。"},{"en":"Each department reviews OKR progress at the end of each quarter.","zh-TW":"每個部門在每季末審查OKR進度。"}]', '{"full form":"objectives and key results"}', NULL, 1, 2145, NULL),
(2146, 'old', '/oʊld/', 'adjective', '{"zh-TW":["舊的；老的"],"en":["having existed for a long time","of a particular age"]}', NULL, 'years old / old-fashioned', '[{"en":"The building is 50 years old.","zh-TW":"這棟大樓有50年歷史。"},{"en":"That approach is old-fashioned now.","zh-TW":"那個方法現在已經過時了。"}]', '{"adjective":"old","noun":"age","verb":"age"}', NULL, 1, 2146, NULL),
(2147, 'ombudsman', '/ˈɒmbʊdzmən/', 'noun', '{"zh-TW":["監察專員；投訴調解專員"],"en":["an official appointed to investigate complaints made by citizens or customers"]}', NULL, 'financial ombudsman / banking ombudsman / contact the ombudsman', '[{"en":"The financial ombudsman resolved the disputed insurance claim.","zh-TW":"金融監察專員解決了有爭議的保險索賠。"},{"en":"She filed a complaint with the banking ombudsman after the bank rejected her claim.","zh-TW":"在銀行拒絕她的索賠後，她向銀行監察專員提出了投訴。"}]', '{"plural":"ombudsmen"}', NULL, 3, 2147, NULL),
(2148, 'omnichannel', '/ˈɒmniˌtʃænəl/', 'adjective', '{"zh-TW":["全渠道的；多渠道整合的"],"en":["providing a seamless customer experience across all channels"]}', NULL, 'omnichannel strategy / omnichannel retail / omnichannel approach', '[{"en":"The retailer''s omnichannel strategy unified online and offline experiences.","zh-TW":"零售商的全渠道策略統一了線上和線下體驗。"},{"en":"Omnichannel customers spend more than single-channel shoppers.","zh-TW":"全渠道客戶比單一渠道購物者花費更多。"}]', '{"noun":"omnichannel"}', NULL, 4, 2148, NULL),
(2149, 'on-boarding', '/ˈɒn bɔːrdɪŋ/', 'noun', '{"zh-TW":["入職培訓；系統導入"],"en":["the process of integrating new employees or customers into an organization or system"]}', NULL, 'design an on-boarding process / on-boarding program', '[{"en":"A structured on-boarding program reduced new hire time-to-productivity.","zh-TW":"結構化的入職培訓計劃縮短了新員工達到生產效率所需的時間。"},{"en":"Customer on-boarding includes account setup and initial product training.","zh-TW":"客戶系統導入包括帳戶設置和初始產品培訓。"}]', NULL, NULL, 4, 2149, NULL);
