(2151, 'on-time', 'ɒn taɪm', 'adjective', '{"zh-TW":["準時的；按時的","及時的"],"en":["arriving at the correct time","not late"]}', NULL, 'on-time delivery/on-time payment', '[{"en":"On-time delivery is critical to our service.","zh-TW":"準時交付對我們的服務至關重要。"}]', '{"adverb":"on time"}', NULL, 3, 2151, NULL),
(2152, 'onboard', '/ˈɒnbɔːrd/', 'verb', '{"zh-TW":["入職；使適應"],"en":["to integrate a new employee or client into an organization"]}', NULL, 'onboard new hires / client onboarding process', '[{"en":"New employees are onboarded through a two-week orientation program.","zh-TW":"新員工通過兩週的入職培訓計劃完成入職。"},{"en":"The company streamlined its client onboarding process to reduce friction.","zh-TW":"公司精簡了客戶入職流程以減少阻力。"}]', '{"noun":"onboarding","adjective":"onboarded"}', NULL, 3, 2152, NULL),
(2153, 'onboarding', '/ˈɒnˌbɔːrdɪŋ/', 'noun', '{"zh-TW":["入職培訓；新員工導入"],"en":["the process of integrating a new employee into an organization"]}', NULL, 'onboarding program / smooth onboarding / onboarding process', '[{"en":"A structured onboarding program helps new hires settle in quickly.","zh-TW":"有組織的入職培訓計劃幫助新員工快速融入。"},{"en":"Remote onboarding requires extra effort to build team connections.","zh-TW":"遠端入職培訓需要額外努力建立團隊聯繫。"}]', '{"verb":"onboard"}', NULL, 4, 2153, NULL),
(2154, 'oncology', '/ɒnˈkɒlədʒi/', 'noun', '{"zh-TW":["腫瘤學；腫瘤科"],"en":["the branch of medicine dealing with cancer"]}', NULL, 'oncology treatment / oncology specialist', '[{"en":"She is receiving oncology treatment for breast cancer.","zh-TW":"她正在接受乳癌的腫瘤治療。"},{"en":"Advances in oncology have improved cancer survival rates.","zh-TW":"腫瘤學的進步提高了癌症存活率。"}]', '{"noun":"oncologist","adjective":"oncological"}', NULL, 3, 2154, NULL),
(2155, 'ongoing', '/ˈɒnɡoʊɪŋ/', 'adjective', '{"zh-TW":["持續進行的"],"en":["continuing; still in progress"]}', NULL, 'ongoing process / ongoing project', '[{"en":"The investigation is still ongoing.","zh-TW":"調查仍在進行中。"},{"en":"We provide ongoing training for staff.","zh-TW":"我們提供持續培訓。"}]', NULL, NULL, 3, 2155, 401),
(2156, 'onshore', '/ˈɒnʃɔːr/', 'adjective', '{"zh-TW":["在岸的；國內的"],"en":["located or occurring within a particular country"]}', NULL, 'onshore banking / onshore operations / onshore investment', '[{"en":"The company moved its treasury operations onshore for compliance.","zh-TW":"公司將其財資業務移至境內以符合合規要求。"},{"en":"Onshore manufacturing reduced logistics complexity.","zh-TW":"在岸製造降低了物流複雜性。"}]', '{"opposite":"offshore"}', NULL, 3, 2156, NULL),
(2157, 'onsite', '/ˈɒnsaɪt/', 'adjective', '{"zh-TW":["現場的；在地的"],"en":["taking place or located at the main workplace or facility"]}', NULL, 'onsite inspection / onsite support / onsite training', '[{"en":"An onsite inspection confirmed the safety standards were met.","zh-TW":"現場檢查確認達到了安全標準。"},{"en":"Onsite support is available Monday through Friday.","zh-TW":"週一至週五提供現場技術支援。"}]', '{"adverb":"onsite"}', NULL, 2, 2157, NULL),
(2158, 'open', '/ˈoʊpən/', 'adjective', '{"zh-TW":["開放的；公開的"],"en":["not closed","available to everyone"]}', NULL, 'open position / open-minded', '[{"en":"We have an open position in marketing.","zh-TW":"我們行銷部有一個空缺職位。"},{"en":"Be open-minded about new ideas.","zh-TW":"對新想法保持開放的心態。"}]', '{"adjective":"open","verb":"open","noun":"opening","adverb":"openly"}', NULL, 1, 2158, NULL),
(2159, 'operate', '/ˈɒpəreɪt/', 'verb', '{"zh-TW":["操作；運作","經營"],"en":["to work or function","to manage"]}', '{"root":{"text":"oper","meaning":"work (工作)"},"suffix":{"text":"-ate","meaning":"使..."}}', 'operate a business / operate machinery', '[{"en":"The company operates in over 30 countries.","zh-TW":"公司在30多國經營。"},{"en":"Only trained staff should operate this.","zh-TW":"只有培訓過的人員能操作。"}]', '{"noun":"operation, operator","adjective":"operational, operative"}', NULL, 3, 2159, 42),
(2160, 'operation', 'ˌɒpəˈreɪʃən', 'noun', '{"zh-TW":["運作；業務","操作"],"en":["a business activity","the way something works"]}', NULL, 'daily operations/overseas operations', '[{"en":"Managing daily operations efficiently.","zh-TW":"高效管理日常運作。"}]', '{"verb":"operate","adjective":"operational","adverb":"operationally"}', NULL, 3, 2160, NULL),
(2161, 'operational', 'ˌɒpəˈreɪʃənəl', 'adjective', '{"zh-TW":["運營的；操作的","可運行的"],"en":["relating to operations","ready to function"]}', NULL, 'operational efficiency/operational costs', '[{"en":"We focus on reducing operational costs.","zh-TW":"我們專注於降低運營成本。"}]', '{"noun":"operation","adverb":"operationally"}', NULL, 4, 2161, NULL),
(2162, 'ophthalmology', '/ˌɒfθælˈmɒlədʒi/', 'noun', '{"zh-TW":["眼科；眼科學"],"en":["the branch of medicine dealing with eye disorders"]}', NULL, 'ophthalmology appointment / ophthalmology clinic', '[{"en":"An ophthalmology examination detected early signs of glaucoma.","zh-TW":"眼科檢查發現了青光眼的早期跡象。"},{"en":"Children should have an ophthalmology checkup before school age.","zh-TW":"兒童應在學齡前接受眼科檢查。"}]', '{"noun":"ophthalmologist","adjective":"ophthalmological"}', NULL, 5, 2162, NULL),
(2163, 'opinion', '/əˈpɪnjən/', 'noun', '{"zh-TW":["意見；看法"],"en":["a personal belief or judgment"]}', '{"root":{"text":"opin","meaning":"think (認為)"},"suffix":{"text":"-ion","meaning":"名詞後綴"}}', 'in my opinion / public opinion', '[{"en":"In my opinion, we should postpone the launch.","zh-TW":"我認為應推遲發布。"},{"en":"Public opinion is shifting.","zh-TW":"民意正在轉變。"}]', '{"adjective":"opinionated"}', NULL, 3, 2163, NULL),
(2164, 'opponent', '/əˈpoʊnənt/', 'noun', '{"zh-TW":["對手；反對者"],"en":["one who competes against"]}', '{"prefix":{"text":"op-","meaning":"against"},"root":{"text":"pon","meaning":"put (放)"},"suffix":{"text":"-ent","meaning":"人"}}', 'political opponent / defeat an opponent', '[{"en":"Our main opponent is a multinational firm.","zh-TW":"我們的主要對手是跨國公司。"},{"en":"She defeated her opponent.","zh-TW":"她擊敗了對手。"}]', '{"verb":"oppose","noun":"opposition","adjective":"opposing"}', NULL, 3, 2164, NULL),
(2165, 'opportunity', '/ˌɒpərˈtjuːnɪti/', 'noun', '{"zh-TW":["機會"],"en":["a chance to do something"]}', '{"root":{"text":"portun","meaning":"port (港口)"},"suffix":{"text":"-ity","meaning":"狀態"}}', 'seize an opportunity / job opportunity', '[{"en":"This internship is a great opportunity.","zh-TW":"這實習是個好機會。"},{"en":"Seize every opportunity to expand.","zh-TW":"抓住每個擴展機會。"}]', '{"adjective":"opportune","noun":"opportunist"}', NULL, 4, 2165, 167),
(2166, 'oppose', '/əˈpoʊz/', 'verb', '{"zh-TW":["反對；對抗"],"en":["to disagree with or resist"]}', '{"prefix":{"text":"op-","meaning":"against"},"root":{"text":"pos","meaning":"put (放)"}}', 'oppose a plan / as opposed to', '[{"en":"Several senators opposed the legislation.","zh-TW":"幾位參議員反對立法。"},{"en":"As opposed to last year, profits increased.","zh-TW":"與去年相反，利潤增加了。"}]', '{"noun":"opposition","adjective":"opposite, opposing"}', NULL, 2, 2166, NULL),
(2167, 'opt', '/ɒpt/', 'verb', '{"zh-TW":["選擇；決定"],"en":["to make a choice"]}', '{"root":{"text":"opt","meaning":"choose (選)"}}', 'opt for / opt out / opt in', '[{"en":"Many employees opted for early retirement.","zh-TW":"許多員工選擇提前退休。"},{"en":"You can opt out of the mailing list.","zh-TW":"你可以退出郵件列表。"}]', '{"noun":"option","adjective":"optional"}', NULL, 1, 2167, NULL),
(2168, 'optimistic', '/ˌɒptɪˈmɪstɪk/', 'adjective', '{"zh-TW":["樂觀的"],"en":["hopeful and confident about the future"]}', '{"root":{"text":"optim","meaning":"best (最好)"},"suffix":{"text":"-istic","meaning":"characterized by (以…為特徵)"},"logic":"以看到最好的面為特徵的，即「樂觀的」。"}', 'optimistic outlook / cautiously optimistic', '[{"en":"She is optimistic about the future.","zh-TW":"她對未來持樂觀態度。"},{"en":"The report paints an optimistic picture.","zh-TW":"報告描繪了樂觀的景象。"}]', '{"noun":"optimism","noun2":"optimist","adverb":"optimistically"}', NULL, 4, 2168, NULL),
(2169, 'optimization', '/ˌɒptɪmaɪˈzeɪʃən/', 'noun', '{"zh-TW":["優化"],"en":["the process of making something as effective or efficient as possible"]}', NULL, 'process optimization / route optimization', '[{"en":"Supply chain optimization reduced delivery times by 20%.","zh-TW":"供應鏈優化將交貨時間縮短了20%。"},{"en":"The company hired a data analyst to assist with pricing optimization.","zh-TW":"公司聘請了數據分析師協助定價優化。"}]', '{"verb":"optimize","adjective":"optimized"}', NULL, 4, 2169, 601),
(2170, 'optimize', '/ˈɒptɪmaɪz/', 'verb', '{"zh-TW":["優化；使最優化"],"en":["to make as effective or efficient as possible"]}', NULL, 'optimize performance / optimize costs / optimize the supply chain', '[{"en":"The engineer optimized the algorithm to run twice as fast.","zh-TW":"工程師優化了算法，使其速度提高了一倍。"},{"en":"Optimizing inventory levels reduced carrying costs significantly.","zh-TW":"優化庫存水準顯著降低了持有成本。"}]', '{"noun":"optimization","adjective":"optimized"}', NULL, 3, 2170, 702),
(2171, 'option', '/ˈɒpʃən/', 'noun', '{"zh-TW":["選項","期權"],"en":["a choice","right to buy/sell at set price"]}', '{"root":{"text":"opt","meaning":"choose (選)"},"suffix":{"text":"-ion","meaning":"名詞後綴"}}', 'available options / stock option', '[{"en":"We have several options to consider.","zh-TW":"我們有幾個選項。"},{"en":"The company offers stock options.","zh-TW":"公司提供股票期權。"}]', '{"adjective":"optional","verb":"opt"}', NULL, 2, 2171, 402),
(2172, 'options', '/ˈɒpʃənz/', 'noun', '{"zh-TW":["選擇權；期權"],"en":["contracts giving the right to buy or sell an asset at a set price"]}', NULL, 'call option / put option / exercise options / options contract', '[{"en":"He bought call options on the rising stock.","zh-TW":"他購買了上漲股票的買入選擇權。"},{"en":"Employee stock options are a common form of compensation.","zh-TW":"員工股票選擇權是一種常見的薪酬形式。"}]', '{"singular":"option"}', NULL, 3, 2172, NULL),
(2173, 'oral', '/ˈɔːrəl/', 'adjective', '{"zh-TW":["口頭的"],"en":["spoken, not written"]}', '{"root":{"text":"or","meaning":"mouth (嘴)"},"suffix":{"text":"-al","meaning":"...的"}}', 'oral presentation / oral agreement', '[{"en":"The contract was only an oral agreement.","zh-TW":"合約只是口頭協議。"},{"en":"Each student must give an oral presentation.","zh-TW":"每人須做口頭報告。"}]', '{"adverb":"orally"}', NULL, 1, 2173, NULL),
(2174, 'orchestra', '/ˈɔːrkɪstrə/', 'noun', '{"zh-TW":["管弦樂團"],"en":["a large group of musicians playing various instruments"]}', '{"root":{"text":"orchestra","meaning":"dancing place (舞蹈場)"},"logic":"源自希臘語，原指劇場中合唱團的表演場地。"}', 'symphony orchestra / orchestra pit', '[{"en":"The orchestra performed Beethoven''s Fifth Symphony.","zh-TW":"管弦樂團演奏了貝多芬第五號交響曲。"},{"en":"She plays violin in the city orchestra.","zh-TW":"她在市立管弦樂團拉小提琴。"}]', '{"adjective":"orchestral","verb":"orchestrate"}', NULL, 3, 2174, NULL),
(2175, 'order', '/ˈɔːrdər/', 'noun', '{"zh-TW":["【主要意義-動詞/名詞】命令；訂單；訂購","【次要意義-名詞】次序；順序；狀態","【次要意義-名詞】（機器）運作狀態"],"en":["[primary] a command; a request to supply goods","[secondary - noun] the arrangement or sequence of things","[secondary - noun] the condition of working properly"]}', NULL, 'in order / out of order / in good working order / order of business / tall order', '[{"en":"The photocopier is out of order until further notice.","zh-TW":"影印機暫時故障，待通知修復。"},{"en":"Please address agenda items in the order listed.","zh-TW":"請按照表格上列出的順序處理議程事項。"},{"en":"Completing this project in two days is a tall order.","zh-TW":"在兩天內完成這個專案要求很高，但我們會盡力。"}]', '{"adjective":"orderly","noun":"orderliness"}', 'order 的次要意義包括「次序」和「運作狀態」，常見片語：out of order（故障/不合規定）、in order（按順序/正常）、tall order（難以完成的要求）均為 TOEIC 高頻表達。', 2, 2175, 43),
